import { z } from "zod";
// Single source of truth for the Bitfab MCP tool surface: name, title,
// description, and input schema for every tool. Both MCP servers import these
// and attach their own handlers - the plugin (bitfab-plugin-lib) proxies to the
// HTTP server, and the HTTP server (bitfab-web) calls mcpService. Before this
// package the two surfaces were hand-duplicated behind five "keep in sync"
// comments, and had drifted on get_span_field.maxChars.
//
// Nothing here may import anything but zod: bitfab-plugin-lib is vendored into
// each editor plugin, so it cannot reach bitfab-web's domain or db modules.
// Where bitfab-web derives an enum from its schema, it asserts at compile time
// that the contract enum still matches (see mcpContractParity.ts).
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
export function parseDateOnly(value) {
    const [year, month, day] = value.split("-").map(Number);
    const date = new Date(0);
    date.setHours(0, 0, 0, 0);
    date.setFullYear(year, month - 1, day);
    return date;
}
const dateOnlyStringSchema = z
    .string()
    .regex(DATE_PATTERN, "Must be YYYY-MM-DD format")
    .refine((value) => {
    const [year, month, day] = value.split("-").map(Number);
    const date = parseDateOnly(value);
    return (date.getFullYear() === year &&
        date.getMonth() === month - 1 &&
        date.getDate() === day);
}, "Must be a valid calendar date");
// get_trace_labels returns only label + annotation + approved per trace (no
// span content), so its payload is bounded and one call can cover a whole
// dataset; get_traces stays capped at 10 because full span content is large.
const GET_TRACE_LABELS_MAX_IDS = 100;
// get_trace_assertions returns assertions only, no span content, so like
// get_trace_labels one call can cover a whole dataset.
const GET_TRACE_ASSERTIONS_MAX_IDS = 100;
const MAX_ASSERTIONS_PER_REQUEST = 50;
// get_grader_labels returns one line per (trace, grader) verdict, so its
// payload scales with graders-per-trace rather than span size.
const GET_GRADER_LABELS_MAX_IDS = 100;
const DEFAULT_GRADER_LABEL_LIMIT = 50;
const MAX_GRADER_LABEL_LIMIT = 200;
// Several MCP clients (Claude Code, Claude Desktop, some SSE clients)
// stringify non-string tool arguments before sending them in `tools/call` -
// numbers, booleans, and arrays all arrive as raw strings even though the
// advertised JSON Schema declares the right types. This is a known upstream
// bug tracked in:
//   - anthropics/claude-code#3966
//   - anthropics/claude-code#5504
//   - anthropics/claude-code#11359
//   - anthropics/claude-code#26094
// Most production MCP servers (Notion, Azure DevOps, FastMCP, ...) defend
// themselves with z.coerce / z.preprocess - we do the same. The advertised
// schema stays strict so the LLM still sees the right types. Use it as
// `z.preprocess(parseJsonString, z.number()...)`. Malformed JSON is left
// as-is so zod can emit a clear "Invalid arguments" error.
//
// Both MCP servers get this for free by sharing the schemas below, so a stdio
// client and a direct HTTP caller are coerced identically. get_span_field's
// maxChars was the one param the old hand-duplicated surfaces disagreed on.
function parseJsonString(val) {
    if (typeof val !== "string") {
        return val;
    }
    try {
        return JSON.parse(val);
    }
    catch {
        return val;
    }
}
// Structured shape for save_trace_plan's `tree`, mirroring bitfab-web's
// tracePlanTreeSchema (src/app/lib/domains/tracePlan.ts). It exists so the
// tool's advertised JSON Schema shows the agent the per-node `analysis` field
// (classification + kind) as a real property instead of burying it in prose:
// with `z.unknown()` the agent never saw `analysis` and shipped plans with every
// node unclassified (LLM calls included). bitfab-web asserts at compile time
// that its own tracePlanTreeSchema still accepts what this shape produces.
// Pre-redesign classification names, mapped onto the current taxonomy so a plan
// carrying legacy labels (e.g. an old stored plan replayed through the tool) is
// accepted here too, matching bitfab-web's own leniency.
const LEGACY_CLASSIFICATION = {
    mock_boundary: "model_call",
    live_side_effect: "side_effect",
};
const traceNodeAnalysisShape = z.object({
    classification: z.preprocess((value) => typeof value === "string"
        ? (LEGACY_CLASSIFICATION[value] ?? value)
        : value, z.enum(["pure", "model_call", "external_read", "side_effect"])),
    mockable: z.boolean().optional(),
    unmockableReason: z.string().min(1).optional(),
    inputSerializable: z.boolean().optional(),
    outputSerializable: z.boolean().optional(),
    innerCall: z.object({ name: z.string().min(1) }).optional(),
    sideEffectKind: z
        .enum([
        "db_write",
        "http_outbound",
        "queue",
        "email",
        "filesystem",
        "vector_write",
    ])
        .optional(),
    readKind: z
        .enum([
        "db_read",
        "http_read",
        "vector_search",
        "cache_read",
        "filesystem_read",
    ])
        .optional(),
});
const traceNodeShape = z.object({
    id: z.string().min(1),
    name: z.string().min(1),
    kind: z.enum(["manual", "auto", "pure"]),
    file: z.string().min(1),
    line: z.number().int().min(0),
    signature: z.string().nullable(),
    parentId: z.string().nullable(),
    childIds: z.array(z.string()),
    framework: z.string().optional(),
    fields: z
        .array(z.object({
        name: z.string().min(1),
        type: z.string().min(1),
        sample: z.unknown().optional(),
    }))
        .optional(),
    sampleInput: z.unknown().optional(),
    sampleOutput: z.unknown().optional(),
    source: z.string().optional(),
    analysis: traceNodeAnalysisShape.optional(),
    // Observed current state of the code, NOT a recommendation. Surfaced as an
    // explicit field for the same reason as `analysis`: so the tool's JSON Schema
    // shows the analyzer these exist and it actually populates them.
    // `alreadyTraced`: an existing span already wraps
    // this node (a hand-written withSpan/@span/bitfab_span, or a framework
    // auto-capture). `alreadyMocked`: that existing span is already tagged to
    // serve its recorded output on replay. Only analyze-repo sets these, when it
    // plans an already-instrumented workflow, so the delta between what's captured
    // now and what it recommends is recorded on the plan for later analysis. This
    // is data tracking only - nothing in the UI renders differently. Omit on
    // greenfield.
    alreadyTraced: z.boolean().optional(),
    alreadyMocked: z.boolean().optional(),
});
const tracePlanTreeShape = z.object({
    rootId: z.string().min(1),
    nodes: z.record(z.string(), traceNodeShape),
});
// registerTool's config argument, without the `name` the contract carries for
// registration and completeness checks. Generic in the input shape so a call
// site naming a contract directly (rather than iterating ALL_TOOL_CONTRACTS)
// keeps full per-tool argument inference in its handler.
export function toolConfig(contract) {
    return {
        title: contract.title,
        description: contract.description,
        inputSchema: contract.inputSchema,
    };
}
