export const searchTraces = {
    name: "search_traces",
    title: "Search Traces",
    description: "Search and filter traces for a traced function. Returns matching traces with IDs, status, timestamps, total duration (ms), total token usage (in/out/cached/total), model, and output preview (all when available). Replay traces (from test runs) carry the same totals. Use get_traces for per-span duration, tokens, time-to-first-token, and model. Supports keyword search, date range, status filter, and regex matching. Use drillDown to refine previous results.",
    inputSchema: {
        traceFunctionKey: z.string().describe("The trace function key to search"),
        searchQuery: z.string().optional().describe("Full-text keyword search"),
        status: z
            .enum(["pending", "completed", "failed"])
            .optional()
            .describe("Filter by trace status"),
        createdAfter: dateOnlyStringSchema
            .optional()
            .describe("Only traces after this date (YYYY-MM-DD)"),
        createdBefore: dateOnlyStringSchema
            .optional()
            .describe("Only traces before this date (YYYY-MM-DD)"),
        traceFilterRegex: z
            .string()
            .optional()
            .describe("Regex to filter trace output"),
        limit: z
            .preprocess(parseJsonString, z.number().int().min(1).max(50))
            .optional()
            .describe("Max traces to return (default 10, max 50)"),
        drillDown: z
            .preprocess(parseJsonString, z.boolean())
            .optional()
            .describe("If true, merge with previous search filters to narrow results"),
        traceIds: z
            .preprocess(parseJsonString, z.array(z.uuid()))
            .optional()
            .describe("Specific trace IDs to fetch"),
        environment: z
            .string()
            .optional()
            .describe("Filter by environment (e.g., production, staging, development, preview). Omit to search across all environments."),
        labelSource: z
            .enum(["human", "agent"])
            .optional()
            .describe('Filter by who authored the label: "human" for human-authored labels only, "agent" for agent-authored labels only. Omit to include any source. This is a pure authorship filter - for trust/validation, use the separate `validated` parameter.'),
        validated: z
            .preprocess(parseJsonString, z.boolean())
            .optional()
            .describe('If true, only return traces with a validated label - a label that is either human-authored OR an agent-authored label that a human has approved (`approvedAt` is set). Use this when you want trustworthy/reviewed labels. Combine with `labelSource: "agent"` to get only approved-agent labels (excluding pure-human labels). Omit (or pass false) to include unapproved labels too.'),
        labelResult: z
            .preprocess(parseJsonString, z.boolean())
            .optional()
            .describe("Filter by label result: true for passing labels, false for failing labels"),
        includeReplays: z
            .preprocess(parseJsonString, z.boolean())
            .optional()
            .describe("Include replayed traces (traces from test runs) in results. Defaults to false because replays have new inputs, not the original production inputs, so they're not useful when selecting traces to label or when sampling real user behavior. Set to true only when you specifically want to inspect replay results."),
        testRunId: z
            .uuid()
            .optional()
            .describe("Filter to traces from a specific experiment (test run). Automatically sets includeReplays to true."),
        datasetId: z
            .uuid()
            .optional()
            .describe("Filter to traces belonging to a specific dataset. Combine with other filters (status, labelResult, etc.) to narrow within the dataset."),
        hasDbSnapshot: z
            .preprocess(parseJsonString, z.boolean())
            .optional()
            .describe("Filter by whether the trace captured a database snapshot reference. true returns only traces that can be replayed against a pinned historical DB branch (the 'Snapshot captured' traces); false returns only traces with no snapshot. Omit to include both."),
    },
};
export const getTraces = {
    name: "get_traces",
    title: "Get Traces",
    description: 'Read one or more traces by ID. Includes inputs, outputs, status, environment tag, trace-level duration (ms), token usage (in/out/cached/total), and model (when available). Use these to compare latency and cost between a trace and its replay. Returns span details (input, output, reasoning, content, context, errors) plus per-span duration, tokens, time-to-first-token, and model when available. Use `scope: "summary"` when scanning many traces to keep the response small; `scope: "full"` when you need the complete untruncated detail of a few traces. To load only labels + annotations for many traces at once (no span content), use get_trace_labels instead.',
    inputSchema: {
        traceIds: z
            .preprocess(parseJsonString, z.array(z.uuid()).min(1).max(10))
            .describe("Trace IDs to read (1-10)"),
        scope: z
            .enum(["summary", "full"])
            .optional()
            .default("summary")
            .describe('Level of span detail. "summary" (default) renders the same span structure as full but caps each span (its fields share a ~1500-char budget) and each trace-level field (~2000 chars), keeping the response small enough not to spill to disk: prefer it when scanning or identifying candidate traces. "full" renders every field untruncated up to 10k chars each, with no per-span ceiling, so reading several large traces can produce a big response: use it when you need complete detail on a handful of traces.'),
    },
};
