export const saveTracePlan = {
    name: "save_trace_plan",
    title: "Save Trace Plan",
    description: 'Create or update a tracing instrumentation plan. CREATE: omit `planId` and send `language`, the full `tree`, `capturedNodeIds`, and usually `traceFunctionKey`; this creates a reviewable plan and returns its id, Studio URL, initial capture count, and expiry. UPDATE: pass `planId`; use targeted `capture` / `uncapture` and/or `mockOnReplayByNodeId` changes without restating the tree, or send `tree` plus `capturedNodeIds` together for a structural replacement. A structural replacement may change `tree.rootId` when the trace boundary moves or is replaced. Targeted changes preserve status; a structural change to a confirmed plan reopens it to `awaiting`. Never create a second plan when one already exists for the work in hand: save it by `planId` instead, and find that id with `list_trace_plans({ traceFunctionKey, status: "awaiting" })` when you do not already hold it (get_trace_plan by key answers only for confirmed plans, so its miss does not mean the key is free). A cancelled plan is the one thing you cannot save onto: create fresh. An expired one needs no special handling, saving it revives it. The captured set must stay one connected sub-tree with exactly one entry point, and that entry point always re-runs live and can never be mocked. Updates return the current plan summary, including the final captured set and replay/mock decisions.',
    inputSchema: {
        planId: z
            .string()
            .optional()
            .describe("Existing trace plan id to update. Omit to create a new plan. Do not send creation-only fields `language`, `source`, or `agentRunId` when this is supplied."),
        language: z
            .enum(["python", "typescript", "ruby", "go"])
            .optional()
            .describe("CREATE mode. Source language of the user's code. Required when `planId` is omitted."),
        // Structured (not z.unknown()) so the tool's JSON Schema shows the agent
        // the per-node `analysis` field instead of burying it in prose, which is
        // how plans arrived with every node unclassified.
        tree: z
            .preprocess(parseJsonString, tracePlanTreeShape)
            .optional()
            .describe("TracePlanTree: { rootId, nodes: { [id]: TraceNode } }. Each TraceNode has id, name, kind ('manual' | 'auto' | 'pure'), file, line, signature, parentId, childIds, plus optional framework, fields, sampleInput, sampleOutput. Every node, including uncaptured context nodes, must carry `analysis` describing WHAT THAT NODE DOES: { classification, sideEffectKind?, readKind?, innerCall?, mockable?, unmockableReason?, inputSerializable?, outputSerializable? }. Set `mockable` mechanically from the node's `kind`: `kind: 'manual'` (a hand-written `withSpan`/`@span`) is mockable, omit `mockable`; `kind: 'auto'` (captured by a framework handler/processor/stream/collector) gets `mockable: false` + `unmockableReason`, the ONE exception being Vercel AI SDK model spans (its `wrapLanguageModel` middleware routes the call through `withSpan`), which are mockable, omit; the root gets omit (never mockable). Rationale: mocking returns a span's recorded output instead of running the call, which only works when the call goes through a `withSpan` wrapper; `auto` framework spans are observed, not wrapped. Key hazard: an `auto` `external_read`/`side_effect` (a framework tool hitting a DB/HTTP) left mockable promises a mock replay can't deliver; its fix is a manual `withSpan` around that call or a db-snapshot, never a mock. Serializability is two raw facts, distinct from `mockable`: set `outputSerializable: false` when the recorded OUTPUT does not round-trip through serialization, and set `inputSerializable: false` when the recorded INPUT does not (its arguments hold a DB client, an open stream, a callback, or a class instance with no JSON form); omit either when it serializes (the default). Two rules follow. (1) Do NOT choose a root whose input is not serializable: replay re-runs the root against its recorded input, so a non-serializable-input root is not replayable, promote the root to a caller that takes a serializable input instead. (2) Do NOT mock a node whose output is not serializable (replay has no recorded value to return); the server enforces this by forcing any `outputSerializable: false` node unmockable, so you don't need to also set `mockable` for that reason. classification is 'pure' (deterministic local compute), 'model_call' (the span that IS the actual LLM/model call; a wrapper/orchestrator whose model call is represented by a child node, e.g. a LangChain chain.invoke or the root, is 'pure', not 'model_call'; never bubble a child's model_call up to its parent), 'external_read' (reads external mutable state: DB SELECT, outbound GET, vector search, cache read; set readKind), or 'side_effect' (mutates external state: DB write, outbound POST/PUT/DELETE, email, queue, payment, filesystem; set sideEffectKind). The server derives the replay disposition (`mockOnReplay`) and the whole validation summary from this classification and mockability, so do NOT send them. Include ~10 surrounding callees below each leaf as `pure` (uncaptured) context nodes so the user can see what's adjacent in the codebase when they edit in the UI. Every node MUST be a descendant of `rootId`: the plan tree renders downward from the root, so a node above the root or on a side branch off one of those ancestors is stored and counted but never drawn. Never send callers above the root."),
        capturedNodeIds: z
            .preprocess(parseJsonString, z.array(z.string()))
            .optional()
            .describe("CREATE or STRUCTURAL update mode. Absolute captured set for `tree`. Required with `tree`; must reference ids in the tree and form one connected sub-tree."),
        capture: z
            .preprocess(parseJsonString, z.array(z.string()))
            .optional()
            .describe("TARGETED update mode. Node ids to add to the existing captured set. Requires `planId`; cannot be combined with `tree` / `capturedNodeIds`."),
        uncapture: z
            .preprocess(parseJsonString, z.array(z.string()))
            .optional()
            .describe("TARGETED update mode. Node ids to remove from the existing captured set. Requires `planId`; cannot be combined with `tree` / `capturedNodeIds`."),
        mockOnReplayByNodeId: z
            .preprocess(parseJsonString, z.record(z.string(), z.boolean()))
            .optional()
            .describe("UPDATE mode. Per-node replay/mock overrides. Only listed nodes change. The replay entry point and framework-observed spans cannot be mocked."),
        stats: z
            .preprocess(parseJsonString, z.unknown())
            .optional()
            .describe("Optional sample-run stats: { durationMs?, tokens?, cost? }"),
        traceFunctionKey: z
            .string()
            .min(1)
            .optional()
            .describe("Trace function key. Recommended when creating; when updating, pass only to rename a key that was wrong or changed."),
        source: z
            .enum(["interactive", "analyze_repo"])
            .optional()
            .describe("CREATE mode. How this plan was produced. Omit for a normal interactive plan; set 'analyze_repo' only from analyze-repo batch mode."),
        agentRunId: z.uuid().optional(),
    },
};
export const confirmTracePlan = {
    name: "confirm_trace_plan",
    title: "Confirm Trace Plan",
    description: "Confirm a trace plan WITHOUT the browser, for the continue path where the user accepted the ASCII plan in chat, or left the Studio plan page without saving. Persists the plan as the latest *confirmed* plan for its traceFunctionKey (so later get_trace_plan by key, setup view, and setup modify can find it) and returns the final captured set plus per-node replay/mock decisions, exactly like get_trace_plan. Studio's Close/Update button does this for the browser path; call this only when the user continues without Studio, or leaves the plan page without saving. Pass the recommended capturedNodeIds; omit mockOnReplayByNodeId to accept the analysis-derived replay decisions (only pass it to override specific nodes the way a Studio toggle would).",
    inputSchema: {
        planId: z
            .string()
            .describe("The trace plan id returned by save_trace_plan."),
        capturedNodeIds: z
            .preprocess(parseJsonString, z.array(z.string()).min(1))
            .describe("The captured set to confirm. Must reference ids present in the plan's tree and form a single connected sub-tree with one entry point (its top-most captured span). The entry point does NOT have to be the plan's tree root: untracing the tree root and rooting at a captured descendant is honored and persisted as-is."),
        mockOnReplayByNodeId: z
            .preprocess(parseJsonString, z.record(z.string(), z.boolean()))
            .optional()
            .describe("Optional per-node overrides of the replay/mock decision (the equivalent of a Studio toggle). Omit to accept the server's analysis-derived defaults. The replay entry point (the top-most captured span) always re-runs live and cannot be mocked."),
    },
};
export const getTracePlan = {
    name: "get_trace_plan",
    title: "Get Trace Plan",
    description: 'Read a trace plan. Two modes: pass `planId` to read a specific plan (use this after save_trace_plan + browser confirmation to learn whether the user confirmed, cancelled, or is still pending); or pass `traceFunctionKey` to fetch the latest *confirmed* plan for that key. A key lookup that reports no plan has ruled out a confirmed one only: unconfirmed plans for that key (an analyze-repo draft, or one whose confirmation never landed) are found with `list_trace_plans({ traceFunctionKey, status: "awaiting" })`, and saving onto one of those beats creating a rival plan for the same key. At the start of a Modify cycle, treat that confirmed plan as historical intent and reconcile its tree and captured nodes with current code; never assume the stored snapshot proves current instrumentation or use it to skip rereading code. Returns the full plan including the tree as JSON.',
    inputSchema: {
        planId: z
            .string()
            .optional()
            .describe("The trace plan id returned by save_trace_plan."),
        traceFunctionKey: z
            .string()
            .optional()
            .describe("Trace function key. Returns the latest confirmed plan for this key in the caller's organization, or a 'no prior plan' message if none exists."),
    },
};
export const listTracePlans = {
    name: "list_trace_plans",
    title: "List Trace Plans",
    description: 'List existing trace plans for this organization, newest first. Two main uses. (1) Surfacing the unconfirmed draft plans an earlier `analyze-repo` run uploaded (pass `source: "analyze_repo"`, `status: "awaiting"`) so an Instrument cycle can reuse them instead of re-scanning the codebase and re-drafting. (2) Finding the plan that already exists for a trace function you are about to save (pass `traceFunctionKey`, and `status: "awaiting"` for the unconfirmed ones get_trace_plan by key does not return), so you update it by `planId` instead of creating a competing plan for the same key. Each entry includes the plan id (pass it to get_trace_plan / save_trace_plan / openTracePlan), the trace function key, the root name and file, language, the recommended captured-node count, status, source, and age. Expired plans are omitted. Use this before asking the user what to instrument.',
    inputSchema: {
        traceFunctionKey: z
            .string()
            .min(1)
            .optional()
            .describe("Filter to plans saved under this exact trace function key. Omit for every key."),
        source: z
            .enum(["interactive", "analyze_repo"])
            .optional()
            .describe("Filter by how the plan was produced. 'analyze_repo' returns the non-interactive batch drafts; 'interactive' returns plans from a normal Instrument/Modify cycle. Omit for both."),
        status: z
            .enum(["awaiting", "confirmed", "cancelled"])
            .optional()
            .describe("Filter by plan status. 'awaiting' is an unconfirmed draft (the reusable ones), 'confirmed' has been accepted in Studio, 'cancelled' was dropped. Omit for any."),
        limit: z
            .preprocess(parseJsonString, z.number().min(1).max(50))
            .optional()
            .describe("Max plans to return (default 20, max 50)"),
    },
};
export const cancelTracePlan = {
    name: "cancel_trace_plan",
    title: "Cancel Trace Plan",
    description: "Retire an `awaiting` trace plan nobody will act on, so it stops coming back from list_trace_plans as a reusable draft. Use it when a draft is moot: its workflow is already instrumented under that key, or the user declined it. Only an awaiting plan can be cancelled, and cancelling is final (a cancelled plan cannot be updated or revived; re-plan the same work with a fresh save_trace_plan). A confirmed plan is the record of what the code captures and is never cancelled. When the draft is worth keeping but wrong, update it with save_trace_plan and its `planId` instead of cancelling and recreating.",
    inputSchema: {
        planId: z
            .string()
            .describe("The trace plan id to cancel. Must still be `awaiting`."),
    },
};
